input.command:
cat > Cargo.toml <<'EOF'
[package]
name = "wintool"
version = "0.1.0"
edition = "2024"
publish = false

# Windows-only: the Win32 bindings are only pulled in when targeting Windows.
[target.'cfg(windows)'.dependencies.windows]
version = "0.62"
features = [
    "Win32_Foundation",
    "Win32_System_SystemInformation",
    "Win32_System_Threading",
]

[profile.release]
lto = true
codegen-units = 1
strip = true
EOF
cat > rust-toolchain.toml <<'EOF'
[toolchain]
channel = "stable"
targets = ["x86_64-pc-windows-msvc"]
EOF
mkdir -p .cargo && cat > .cargo/config.toml <<'EOF'
# Statically link the C runtime so the binary has no VC++ redistributable dependency.
[target.'cfg(all(windows, target_env = "msvc"))']
rustflags = ["-C", "target-feature=+crt-static"]
EOF
cat > src/main.rs <<'EOF'
#[cfg(not(windows))]
compile_error!("wintool only supports Windows targets (e.g. --target x86_64-pc-windows-msvc)");

use windows::Win32::System::SystemInformation::{GetSystemInfo, GetTickCount64, SYSTEM_INFO};
use windows::Win32::System::Threading::GetCurrentProcessId;

fn main() -> windows::core::Result<()> {
    // SAFETY: these Win32 calls have no preconditions; GetSystemInfo writes into a
    // properly sized, stack-allocated SYSTEM_INFO.
    let (pid, uptime_ms, info) = unsafe {
        let mut info = SYSTEM_INFO::default();
        GetSystemInfo(&mut info);
        (GetCurrentProcessId(), GetTickCount64(), info)
    };

    println!("pid:        {pid}");
    println!("processors: {}", info.dwNumberOfProcessors);
    println!("page size:  {} bytes", info.dwPageSize);
    println!("uptime:     {}s", uptime_ms / 1000);
    Ok(())
}
EOF
cat .gitignore; rustup target add x86_64-pc-windows-msvc 2>&1 | tail -1; cargo check --target x86_64-pc-windows-msvc 2>&1 | tail -5; echo ---; cargo check 2>&1 | grep -E "^error" | head -3

